private void checkTriple(String predicate, VerificationMode verificationMode) throws TripleHandlerException {
    final String DOCUMENT_IRI = "http://an.html.page";
    final TripleHandler mockTripleHandler = mock(TripleHandler.class);
    final ValueFactory valueFactory = SimpleValueFactory.getInstance();
    ExtractionContext extractionContext = new ExtractionContext("test-extractor", valueFactory.createIRI(DOCUMENT_IRI));
    final IgnoreAccidentalRDFa ignoreAccidentalRDFa = new IgnoreAccidentalRDFa(mockTripleHandler, true);
    ignoreAccidentalRDFa.openContext(extractionContext);
    ignoreAccidentalRDFa.receiveTriple(valueFactory.createIRI(DOCUMENT_IRI), valueFactory.createIRI(predicate), valueFactory.createIRI("http://www.myedu.com/modules/20110519065453/profile.css"), valueFactory.createIRI(DOCUMENT_IRI), extractionContext);
    ignoreAccidentalRDFa.close();
    verify(mockTripleHandler, verificationMode).receiveTriple((Resource) any(), (IRI) any(), (Value) any(), (IRI) any(), (ExtractionContext) any());
}

